import{_t as e,it as t,n,rt as r}from"./chunks/framework.DmGhRbf7.js";var i=JSON.parse(`{"title":"Manage forms in the CHEFS Forms options page","description":"","frontmatter":{},"headers":[],"relativePath":"content/plugins/bcew-chefs-embed/user/manage-forms-in-the-chefs-forms-options-page.md","filePath":"content/plugins/bcew-chefs-embed/user/manage-forms-in-the-chefs-forms-options-page.md"}`),a={name:`content/plugins/bcew-chefs-embed/user/manage-forms-in-the-chefs-forms-options-page.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="manage-forms-in-the-chefs-forms-options-page" tabindex="-1">Manage forms in the CHEFS Forms options page <a class="header-anchor" href="#manage-forms-in-the-chefs-forms-options-page" aria-label="Permalink to “Manage forms in the CHEFS Forms options page”">​</a></h1><p>Open WordPress Admin and go to CHEFS Forms.</p><h2 id="add-a-new-form" tabindex="-1">Add a new form <a class="header-anchor" href="#add-a-new-form" aria-label="Permalink to “Add a new form”">​</a></h2><ol><li>Enter a Form ID.</li><li>Enter the API Key for that form.</li><li>Click <strong>Save</strong>.</li></ol><p>CHEFS validates the Form ID and API key before WordPress saves them. If the credentials are invalid, the form is not added or updated. You may see an error when the Form ID cannot be found, the API key is invalid, or CHEFS is temporarily unavailable, or the form has no published version.</p><p>After you save:</p><ul><li>CHEFS confirms the credentials and the form title is stored in WordPress.</li><li>The form title is shown in the Configured Forms list, with the Form ID retained for support.</li><li>The form title becomes available in the CHEFS Form block options.</li></ul><p>If CHEFS cannot confirm the credentials, the form is not saved.</p><p>The Configured Forms table includes:</p><ul><li>Form ID</li><li>Form title</li><li>Date added</li><li>Confirmation message</li><li>Actions: <ul><li>Remove form</li><li>Edit confirmation</li></ul></li></ul><p>Note: API keys are hidden for security reasons.</p><h2 id="remove-a-form" tabindex="-1">Remove a form <a class="header-anchor" href="#remove-a-form" aria-label="Permalink to “Remove a form”">​</a></h2><p>Click <strong>Remove form</strong> next to the form you want to remove. A confirmation dialog asks you to confirm this cannot be undone. Choose <strong>Cancel</strong> to keep the form, or <strong>OK</strong> to remove it.</p><p>After you confirm removal:</p><ul><li>The saved Form ID and API key are removed.</li><li>The form is removed from block selection options.</li><li>The custom confirmation for that form is also removed.</li></ul><p>Note: Removing a form here does not delete the form in CHEFS. Any WordPress page embedding it will show an error until the form is saved again or the block is removed.</p><h2 id="update-an-api-key-or-change-a-form-id" tabindex="-1">Update an API key or change a Form ID <a class="header-anchor" href="#update-an-api-key-or-change-a-form-id" aria-label="Permalink to “Update an API key or change a Form ID”">​</a></h2><p>To update an API key, enter the same Form ID with the new API key and click <strong>Save</strong>. CHEFS validates the replacement credentials before WordPress updates the saved form.</p><p>Updating the API key does not change the saved form title, custom confirmation, or block embed settings. Only the credentials for that Form ID are replaced.</p><p>If validation fails, the existing saved Form ID and API key remain unchanged.</p><p>To change the Form ID, first remove the old form from the Configured Forms list, then add the new Form ID and its API key as a new form. Saving a different Form ID creates an additional configured form; it does not replace the existing row, so the old Form ID remains available in the block picker until you remove it.</p>`,21)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};